command:
$ErrorActionPreference="Stop"
$expectedMain="20876753e83c391cd35e0b792b864b576e21bafe"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
if(-not (Test-Path -LiteralPath $repo -PathType Container)){throw "Canonical checkout unavailable"}
& git -C $repo fetch origin main --no-tags
if($LASTEXITCODE -ne 0){throw "Main fetch failed"}
$gotMain=(& git -C $repo rev-parse refs/remotes/origin/main).Trim()
if($LASTEXITCODE -ne 0 -or $gotMain -ne $expectedMain){throw "Main moved: refuse branch cleanup"}
$targets=@(
  @{Name="feat/search-v3-indexed-extension";Sha="68b72ec5475694913f82351557dc1ba479629c25"},
  @{Name="feat/search-v3-indexed-extension-integration";Sha="70e93203ac628744a4f85c4b8bc6466f308bbcb2"},
  @{Name="feat/search-v3-indexed-size";Sha="09851775bf18340ccaf471313c380b474a17b7f6"},
  @{Name="feat/search-v3-indexed-modified-date";Sha="20876753e83c391cd35e0b792b864b576e21bafe"}
)
foreach($entry in $targets){
  $ref="refs/heads/$($entry.Name)"
  $remote=@(& git -C $repo ls-remote --heads origin $ref)
  if($LASTEXITCODE -ne 0 -or $remote.Count -ne 1){throw "Missing or ambiguous remote ref: $ref"}
  $remoteSha=([string]$remote[0] -split '\s+')[0].ToLowerInvariant()
  if($remoteSha -ne $entry.Sha){throw "Ref SHA changed: $ref"}
}
Write-Host "BRANCH_CLEANUP_PREFLIGHT=PASS targets=4"
foreach($entry in $targets){
  $ref="refs/heads/$($entry.Name)"
  $lease="--force-with-lease=$($ref):$($entry.Sha)"
  & git -C $repo push $lease origin ":$ref"
  if($LASTEXITCODE -ne 0){throw "Failed branch deletion: $ref"}
  Write-Host "BRANCH_CLEANUP_DELETED=$($entry.Name)"
}
$remaining=@(& git -C $repo ls-remote --heads origin)
if($LASTEXITCODE -ne 0){throw "Remote branches listing failed"}
$names=@($remaining | ForEach-Object { if($_ -match "refs/heads/(.+)$"){ $Matches[1] } })
$required=@("main","control/remote-shell","evidence/remote-windows","fix/central-ci-m19-m20-panel-handoff")
$unexpected=@($names | Where-Object {$_ -notin $required})
$missing=@($required | Where-Object {$_ -notin $names})
if($unexpected.Count -ne 0 -or $missing.Count -ne 0){throw "Unexpected remaining branches: $($names -join ',')"}
Write-Host "BRANCH_CLEANUP_VERIFIED=PASS remaining=$($names -join ',')"
